    this.prepareNextTurn,
    this.overWindowRelief,
    this.getSteeringMessages,
    this.getFollowUpMessages,
    this.steeringNotifications,
    this.hasPendingSteering,
    this.maxEmptyRetries = 1,
    this.maxSteeringTurns = 20,
    this.contextWindowCap,
    this.wireDump = false,
    this.toolMisuseBreaker,
    this.stuckTool,
    this.finalizeGate = false,
    this.operativeSkills = const [],
    this.reportedOrphanKeys,
    this.budgetLineProvider,
  });

