    // calls) reads as a hang; nudge the model once with "continue".
    if (_shouldContinueAfterEmptyReply(lastMessage)) {
      _emptyReplyNudgesLeft--;
      await _runPrompt('continue', isAutoContinue: true);
      return false;
    }
    return true;
  }

