    // full (short lines stay under its line cap; ~46k chars ≈ 11.5k
    // estimated tokens) — not a split assistant turn, so the classic
    // prefix compaction hides it cleanly.
    env.writeFile('big.txt', List.filled(1000, 'x' * 45).join('\n'));
  });

  tearDown(() {
