    } catch (_) {
      // A failed relief = no relief; the error below is the answer —
      // unless the failure WAS a cancellation (user abort mid-relief,
      // issue #1085): that must surface as aborted, never as the
      // guard error.
      if (_isCancelRequested(cancelToken)) {
