```dart
Future<(AssistantMessage, Context)> _retryDegenerateEmpty(
  AssistantMessage message,
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  StreamFunction streamFunction,
  CancelToken? cancelToken,
) async {
  var generic = 0;
  var hiccup = 0;
  var current = message;
  var out = context;
  while (_isDegenerateEmpty(current) && !(cancelToken?.isCancelled ?? false)) {
    if (generic < config.maxEmptyRetries) {
      generic++;
    } else {
      // gh-1577: an empty completion that follows partial content ...
      if (classifyEmptyCompletion(out.messages, current) !=
          EmptyCompletionVerdict.emptyAfterPartial) {
        break;
      }
      if (hiccup >= config.emptyHiccupRetries) {
        current = await _emptyHiccupExhausted(current, out, config, emit, hiccup);
        break;
      }
      await _emptyHiccupBackoff(hiccup, config);
      hiccup++;
    }
    (current, out) = await _streamAssistantResponse(out, config, emit, streamFunction, cancelToken);
  }
  if (_isDegenerateEmpty(current) && (cancelToken?.isCancelled ?? false)) {
    // abort raced the empty settle (E5): the abort wins — never a silent empty.
    current = await _finishWithoutStream(out, emit, _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'), ...);
  }
  return (current, out);
}
```

