```dart
EmptyCompletionVerdict classifyEmptyCompletion(
  List<Message> turnHistory,
  AssistantMessage message,
) {
  if (!isEmptyAssistantCompletion(message)) {
    return EmptyCompletionVerdict.notEmpty;
  }
  switch (message.stopReason) {
    case StopReason.error || StopReason.aborted:
      return EmptyCompletionVerdict.abortedOrError;
    default:
      break;
  }
  if (_turnCarriesPartialContent(turnHistory, message)) {
    return EmptyCompletionVerdict.emptyAfterPartial;
  }
  return EmptyCompletionVerdict.cleanEmpty;
}

bool _turnCarriesPartialContent(List<Message> turnHistory, AssistantMessage message) {
  // The classified message itself: a truncation signal on it is partial
  // evidence even though its own content is empty (a stream cut before
  // anything arrived).
  if (_carriesTruncationSignal(message)) return true;
  var sawSelf = false;
  for (final m in turnHistory.reversed) {
    if (!sawSelf && identical(m, message)) { sawSelf = true; continue; }
    if (m is UserMessage) break; // the window is the turn: stop at the prompt
    switch (m) {
      case AssistantMessage():
        if (_hasActionableContent(m)) return true;
        if (_carriesTruncationSignal(m)) return true;
      case ToolResultMessage():
        return true; // tool activity
      default: break;
    }
  }
  return false;
}

bool _carriesTruncationSignal(AssistantMessage m) =>
    m.stopReason == StopReason.length ||
    (m.stopReason == StopReason.stop && m.errorMessage != null);
```

