    /// CLI-shaped loop config: the CLI's own nudge owns clean empties
    /// (`maxEmptyRetries: 0`), the hiccup budget is the loop's.
    AgentLoopConfig cliShapeConfig() => const AgentLoopConfig(
      model: _model,
      maxEmptyRetries: 0,
      emptyHiccupBaseDelay: Duration.zero,
    );

