          emptyTurn,
          _textTurn('recovered'),
        ]);
        final stream = agentLoop(
          prompts: [UserMessage.text('do the task')],
          context: const Context(messages: []),
          config: cliShapeConfig(),
          streamFunction: fake.call,
          toolExecutor: (_, _, _) async => ToolExecutionResult.text('done'),
        );

