        final stream = FakeStreamFunction([emptyTurn(), emptyTurn()]);
        final cli = cliFor(stream);
        final run = cli.run();
        io.sendLine('hi');
        for (var i = 0; i < 400; i++) {
          if (stream.calls >= 2 && !cli.isBusy) break;
          await Future<void>.delayed(const Duration(milliseconds: 25));
