Future<(AssistantMessage, Context)> _retryDegenerateEmpty(
  AssistantMessage message,
  Context context,
  AgentLoopConfig config,
  AgentEventSink emit,
  StreamFunction streamFunction,
  CancelToken? cancelToken,
) async {
  var generic = 0;
  var hiccup = 0;
  var current = message;
  var out = context;
  var cancelled = cancelToken?.isCancelled ?? false;
  while (_isDegenerateEmpty(current) && !cancelled) {
    if (generic < config.maxEmptyRetries) {
      generic++;
    } else {
      if (classifyEmptyCompletion(out.messages, current) !=
          EmptyCompletionVerdict.emptyAfterPartial) {
        break;
      }
      if (hiccup >= config.emptyHiccupRetries) {
        // gh-1577 exhaustion verdict
        current = await _finishWithoutStream(
          out,
          emit,
          _terminalMessage(
            config.model,
            StopReason.error,
            emptyHiccupExhaustedError(
              retryCount: hiccup,
              attempts: 1 + generic + hiccup,
              lastStopReason: current.stopReason,
            ),
          ),
        );
        break;
      }
      final delay = emptyHiccupBackoffFor(
        hiccup,
        baseDelay: config.emptyHiccupBaseDelay,
        maxBackoff: config.emptyHiccupMaxBackoff,
      );
      if (delay > Duration.zero) await Future<void>.delayed(delay);
      hiccup++;
    }
    (current, out) = await _streamAssistantResponse(
      out, config, emit, streamFunction, cancelToken,
    );
    cancelled = cancelToken?.isCancelled ?? false;
  }
  if (cancelled && _isDegenerateEmpty(current)) {
    // E5: the abort raced the empty classification — the abort wins.
    current = await _finishWithoutStream(
      out, emit,
      _terminalMessage(config.model, StopReason.aborted, 'Operation aborted'),
    );
  }
  return (current, out);
}
```

