          assistant(
            content: [TextContent(text: 'truncated back then')],
            stopReason: StopReason.length,
          ),
          ToolResultMessage(
            toolCallId: 'c9',
            toolName: 'bash',
            content: [TextContent(text: 'out')],
            isError: false,
            timestamp: DateTime.utc(2026),
          ),
          // A fresh logical turn begins here.
          UserMessage.text('new question'),
