        final turn = [
          UserMessage.text('go'),
          assistant(
            errorMessage:
                'stream ended without finish_reason — the reply may be '
                'truncated',
          ),
        ];
        expect(
          classifyEmptyCompletion(turn, turn.last),
          EmptyCompletionVerdict.emptyAfterPartial,
        );
      },
    );
  });

