    if (_emptyReplyNudgesLeft <= 0) return false;
    if (lastMessage is! AssistantMessage) return false;
    return classifyEmptyCompletion(_agent.state.messages, lastMessage) ==
        EmptyCompletionVerdict.cleanEmpty;
